import numpy as np

data = np.array([4, 8, 6, 5, 3])

def mse(prediction, data):
    return np.mean((data - prediction) ** 2)

# try several candidate predictions
for candidate in [4.0, 5.0, 5.2, 6.0]:
    print(candidate, mse(candidate, data))
# the minimum mse occurs exactly at 5.2, the mean of the data
